  "year": -1700000,
  "date": "约170万年前",
  "title": "元谋人",
  "short": "中国境内已知最早的直立人，发现于云南元谋，已会使用简单石器。",
  "detail": "元谋人，又称元谋猿人或元谋直立人，是在中国发现的直立人化石。1965年发现于云南元谋上那蚌村附近，共计左右门齿两颗。后来还发现了石器、炭屑、和有人工痕迹的动物肢骨等。早期依据对化石地层和动物群结合古地磁结果，认为元谋人的距今年代为170万年左右，是属于旧石器时代早期的古人类。但随后有学者根据新的古地磁结果，提出其年代应为70万年左右。尽管最新的古地磁年代显示遗址年代应为170万年，该遗址年代目前依旧存在争议。元谋人属于直立人，当代东亚人属于智人，两者之间是否有亲缘关系，尚未有定论。",
