  "title": "北京人",
  "short": "周口店发现的直立人，会使用天然火、制作打制石器。",
  "detail": "北京猿人 又称北京人、北京直立人、中国猿人北京种，是生活在更新世，属于已经灭绝的直立人的一支。其化石遗存于1927年，在中华民国北京西南的周口店龙骨山发现。关于其年代的争议较大，一般认为约在距今50万年前。而2009年英国《自然》期刊发表的应用26Al/10Be测年法的结果则把这一年代上推至68万－80万年前。",
