  "title": "山顶洞人",
  "short": "晚期智人，已掌握磨制和钻孔技术，会用骨针缝制衣物。",
  "detail": "山顶洞人指发现于中国北方的晚期智人化石。因化石地点在周口店龙骨山顶部，北京猿人洞穴上方的“山顶洞”内而得名。其重要化石及遗物均在1941年二次世界大战期间随同北京猿人标本一起丢失而下落不明。山顶洞堆积已全部挖光，原来的洞顶已被挖掉。今后也不会再有新的发现。虽然山顶洞人化石已难于寻觅，但当时对重要的化石均制作了品质精良的模型。原始模型目前保存在中国科学院古脊椎动物与古人类研究所，科学家基本可以通过对模型的观测研究化石提供的信息。",
