  "title": "仰韶文化",
  "short": "黄河中游新石器文化，以精美彩陶著称，过着定居农耕生活。",
  "detail": "仰韶文化（公元前5000年—前2700年）是黄河中游地区重要的新石器时代中期考古学文化，分布在整个黄河中游从今天的中华人民共和国甘肃省到河南省之间，西至河湟，北至河套，东至太行山−豫东，南至淮河–汉水流域，以关中豫西晋南地区为中心的广大区域。仰韶文化因最早发现于河南渑池仰韶村而得名；由于遗存中多带彩色花纹的陶器，故也曾称“彩陶文化”。",
