  "title": "良渚文化",
  "short": "以玉琮等精美玉器和大型古城水利系统闻名，实证中华五千年文明。",
  "detail": "良渚文化，距今5300年至4000年期间，中国新石器时代考古学文化之一，出现并发展于长江下游环太湖地区，共发现500多处遗址，以良渚遗址附近的莫角山为中心区。良渚文化最主要特征是玉器的使用和随葬，包括大件的玉琮、玉璧、玉钺。玉琮是工艺最精、最具权威性的玉器，往往刻有精致的兽面纹，是神灵的图象，玉钺则是军权、王权的象征。良渚文化的政治体为酋邦，亦有学者认为已出现国家雏形，能动员大量劳动力，各酋邦间结成联盟，神权色彩浓厚，建造大型祭祀场所、城墙及防洪土墙，社会成员地位分化，形成贵族和普通平民阶层。",
