  "title": "涿鹿之战",
  "short": "传说黄帝联合炎帝在涿鹿击败蚩尤，华夏部落联盟形成。",
  "detail": "涿鹿之战是相传中国远古时代的一场战争，发生在今河北涿鹿一带。主要文献记载，黄帝联合炎帝部落，与东方九黎部落首领蚩尤交战。传说蚩尤作大雾，使黄帝军队迷失方向，黄帝造指南车辨别方向，最终击败并擒杀蚩尤。另有文献认为，在此之前黄帝与炎帝曾在阪泉交战。涿鹿之战后，黄帝被各部落尊为共主，炎黄部落逐渐融合，形成华夏族的主体，因此中国人自称“炎黄子孙”。",
