  "id": "e014",
  "year": -1046,
  "date": "前1046年",
  "title": "牧野之战",
  "short": "周武王联合各路诸侯在牧野大败商纣王军队，商朝灭亡，周朝建立。",
  "detail": "牧野之战是商朝末期的关键会战，多认为发生于前1046年的中原，周武王统帅的周人军队乘殷商主力东征东夷时，出兵攻伐殷商。殷商在此战战败，帝辛（纣）自尽，商朝灭亡。后世称“武王克殷”、“武王克商”、“武王伐纣”。",
