  "title": "修筑万里长城",
  "short": "秦始皇连接各国旧长城以抵御匈奴，成为中华民族的象征。",
  "detail": "长城是在中国大陆华北一带历朝修筑的大规模军用隔离墙的统称，旨在抵御来自欧亚草原的游牧民族入侵。长城并非单一结构，而是分成多节矗立于险要之处，并设有多个关口，实际上亦是帝国边境经济贸易的重要一环，东西段与前后关卡加总起来可绵延上万华里（约4500-6000公里），因此又称作万里长城。",
