  "title": "秦始皇陵兵马俑",
  "short": "秦始皇陵的大型陪葬坑，数千陶俑栩栩如生，被誉为“世界第八大奇迹”。",
  "detail": "秦始皇兵马俑，又称秦始皇陵兵马俑、秦陵兵马俑，是秦始皇陵东侧大型陪葬坑中出土的陶质军队群像，位于中华人民共和国陕西省西安市临潼区。兵马俑坑于1974年由当地村民打井时发现，随后展开考古发掘，现已确认一号、二号、三号坑等遗迹。",
