  "detail": "赤壁之战是东汉末年曹操南攻刘表、刘备、孙权之战役，亦可单指发生于长江赤壁、乌林一线的决战。该战是三国时期“三大战役”之一，也是中国历史上以少胜多的著名战事。在赤壁的决战是首次发生于长江流域的大规模水战。",
