  "title": "三国鼎立",
  "short": "曹丕代汉建立魏国，其后刘备、孙权相继称帝，形成魏蜀吴三国鼎立。",
  "detail": "三国 是曹魏、蜀汉及孙吴三个国家并立的中国历史时期，也是魏晋南北朝和六朝的开端时期。一般认为是从建安元年起算。东汉末年战争不断，使得人口急剧下降，经济严重损害，因此三国皆重视经济发展，加上战争带来的需求，各种技术都有许多进步。",
