  "date": "353年",
  "title": "兰亭集序",
  "short": "王羲之在兰亭雅集时写下《兰亭集序》，被后世誉为“天下第一行书”。",
  "detail": "《兰亭集序》，又称作《兰亭序》、《兰亭叙》、《兰亭帖》、《禊序》、《禊帖》、《临河序》、《兰亭宴集序》，为东晋书法家王羲之所作，有“天下第一行书”之称，是晋代书法成就的代表。《兰亭集序》共计324字，凡是重复的字都各不相同，其中21个“之”字，各具风韵，皆无雷同。王羲之酒醒之后，过几天又把原文重写了好多本，但终究没有在兰亭集会时所写的好。",
