  "date": "383年",
  "title": "淝水之战",
  "short": "东晋八万军队击败前秦大军，以少胜多，留下“草木皆兵”等典故。",
  "detail": "淝水之战，又称肥水之战，发生于东晋太元八年（前秦建元十九年）（383年），前秦出兵伐晋，于淝水（今安徽省淮南市寿县东南方）交战。最终，东晋仅以七万余军力大胜号称八十余万前秦军，是中国历史上著名的以少胜多的战例，确定了南北朝时期长期分裂的格局。",
