  "date": "493年起",
  "title": "开凿龙门石窟",
  "short": "中国石刻艺术宝库，与云冈、莫高窟并称三大石窟。",
  "detail": "龙门石窟位于中华人民共和国河南省洛阳市南郊12公里处的伊水两岸的龙门山和香山崖壁上，主要开凿于北魏至北宋的四百余年间，至今仍存有窟龛（或称壁龛）2100多个，造像10万余尊，碑刻题记3600余品，多在伊水西岸。数量之多位于中国各大石窟之首。其中“龙门二十品”是书法魏碑精华，唐代书法家褚遂良所书的“伊阙佛龛之碑”则是初唐楷书艺术的典范。",
