  "year": 606,
  "date": "约606年",
  "title": "科举制创立",
  "short": "隋朝开创以考试选拔官员的科举制度，延续一千三百年。",
  "detail": "科举是一种通过考试来选拔官员的制度，源自中国，并传播至汉字文化圈其他国家。它是古代中国的一项重要政治制度，对中国社会和文化产生巨大影响，直接催生不论门第、以考试产生的“士大夫”阶层。除中国科举外，邻近中国的亚洲国家如越南、朝鲜半岛、琉球群岛和日本列岛也曾引入这种制度来选拔人才。",
