  "id": "e059",
  "year": 1127,
  "date": "1127年",
  "title": "靖康之变",
  "short": "金军攻破开封，俘虏徽钦二帝，北宋灭亡，南宋建立。",
  "detail": "靖康之变，又称靖康之耻、靖康之祸、靖康之乱、靖康之难，是指公元1125年至1127年，来自北方的女真族攻陷北宋首都汴梁（今河南省开封市），掳走皇帝宋钦宗、太上皇宋徽宗、几乎全部宋太宗一系皇族、后妃、官吏及逾十万首都平民的重大战争。城破于宋钦宗靖康元年（丙午年）闰十一月二十五日，因而得名。",
