  "year": 1140,
  "date": "1140年",
  "title": "岳飞抗金",
  "short": "岳家军在郾城大破金军精锐，金人感叹“撼山易，撼岳家军难”。",
  "detail": "岳飞（1103年3月24日—1142年1月27日），字鹏举，宋朝相州汤阴（今河南省安阳市汤阴县）人。南宋抗金名将及民族英雄，官至少保、枢密副使，受封武昌郡开国公。遭大臣秦桧等人诬陷而被宋高宗赐死。多年后，宋孝宗为其平反，追谥武穆。后被南宋其他皇帝追赠太师。 后世多称呼其为岳武穆、武穆王、岳忠武王。",
