  "date": "1206年",
  "title": "成吉思汗统一蒙古",
  "short": "铁木真统一蒙古高原各部，被推举为成吉思汗，建立强大的大蒙古国。",
  "detail": "成吉思汗（约1162年—1227年8月25日），本名铁木真，是大蒙古国的创建者，被后世元朝追尊为元太祖。成吉思汗一生大多时光都用于统合蒙古族诸部落，继而发起连番军事征伐，征服中国及中亚的大片疆土。",
