  "year": 1368,
  "date": "1368年",
  "title": "明朝建立",
  "short": "朱元璋在南京称帝，建立明朝，随后北伐推翻元朝。",
  "detail": "明朝（1368年—1644年）是中国历史上继元朝之后的大一统王朝，也是最后一个由汉族建立的大一统朝代，历经十二世、十六位皇帝，国祚二百七十六年。元末农民起义中，朱元璋逐步消灭各路割据势力，于1368年在应天府（今南京）称帝，国号大明，年号洪武，同年派兵北伐攻占大都，结束了元朝在中原的统治。明朝初期废除丞相、加强中央集权，后明成祖迁都北京。明代手工业和商品经济繁荣，出现资本主义萌芽，郑和下西洋、修建长城与紫禁城等都发生在这一时期。",
