  "short": "郑和率领庞大船队七下西洋，访问三十多个国家，最远到达东非沿岸。",
  "detail": "郑和下西洋，是指中国在明代早期（1405年至1433年）间的七场连续的大规模远洋航海，跨越了东亚地区、东南亚地区、印度次大陆、阿拉伯半岛、以及东非各地，被认为是当时世界上规模最大的远洋航海项目。",
