  "detail": "《本草纲目》是一部集中国16世纪以前本草学大成的著作，明代万历六年（1578年）定稿，万历二十三年（1596年）在南京正式刊行，作者为医学家、药学家和博物学家李时珍。此著收录于《四库全书》，为子部医家类。",
