  "year": 1662,
  "date": "1662年",
  "title": "郑成功收复台湾",
  "short": "郑成功率军渡海击败荷兰殖民者，收复被侵占三十多年的宝岛台湾。",
  "detail": "郑成功（1624年8月27日—1662年6月23日），赐姓朱名成功，原名森，字明俨、大木，幼名福松，通称郑成功，自称国姓成功，尊称国姓爷。南明招讨大将军、延平王，明郑政权建立者，谥号武，其领导的明郑为明末清初持续时间最久的反清复明势力。因曾受南明隆武帝赐国姓朱而被尊称为“国姓爷”，西方世界取其音拼作“Koxinga”。",
