  "title": "尼布楚条约",
  "short": "中俄两国签订的第一个边界条约，划定了两国东段边界，维护了主权。",
  "detail": "《尼布楚条约》，俄方称《涅尔琴斯克条约》，是清朝和俄罗斯沙皇国于1689年签订的第一份边界条约，也是中国历史上首次在国际法的精神下签订的条约。签订条约的结果使双方分据广大土地，并一度阻挡俄国的东扩。",
