  "year": 1782,
  "date": "1782年",
  "title": "《四库全书》完成",
  "short": "乾隆帝下令编修的中国古代最大丛书，分经史子集四部，历时十余年。",
  "detail": "《四库全书》是中国古代最大的丛书，由清朝乾隆帝于乾隆三十八年（1772年）开始编修，至乾隆四十六年（1783年）编成第一套，历时11年。整书一共收书3,503种、79,337卷，约9.97亿字。《四库全书》当中之书籍以传统的四部分类法分类，包括“经”、“史”、“子”、“集”四部；每部之下又另以“属”作分类，整书一共有44类、66属。封面按其所属的部使用了不同的颜色：经部为葵绿色、史部为红色、子部为蓝色、集部为灰色。《四库全书》每页16行21字，用楷书。",
