  "date": "1842年",
  "title": "鸦片战争与《南京条约》",
  "short": "清朝战败签订《南京条约》，中国开始沦为半殖民地半封建社会。",
  "detail": "第一次鸦片战争，又称鸦片战争、中英战争，是公元1840年至1842年（道光二十年至二十二年）期间，大清帝国和大英帝国之间的一系列军事冲突。此场战争是近代西方国家对中国发起的第一次大规模战争，船坚炮利迫使清政府打开闭关锁国的大门，被认为是中国近代史的开端。",
