  "short": "英法联军攻入北京，劫掠并焚毁“万园之园”圆明园。",
  "detail": "圆明园是清朝兴建的大型皇家园林，康熙帝赐此园予皇四子胤禛（法号圆明居士），并提匾“圆明”。供清帝盛夏避暑、听政，处理军政事务，位于现今中华人民共和国北京市海淀区。与长春园，绮春园合称为“圆明三园”，占地面积3.5平方公里，建筑面积达16万平方米，约合5,200亩一百五十余景，有“万园之园”之称。",
