  "short": "武昌起义爆发，推翻清朝，结束两千多年君主专制。",
  "detail": "辛亥革命，又称1911年革命、一次革命，是指始于1911年（辛亥年）清朝武昌起义爆发后，共和派革命军成功使清宣统帝退位的革命；在广义上也指1894年至1912年由兴中会、同盟会等组织的各种反清革命运动。",
