  "detail": "中国共产党第一次全国代表大会，简称中共一大，于1921年7月23日在上海法租界秘密召开，7月30日会场被租界巡捕房搜查后休会，8月3日在浙江省钱塘道嘉兴一艘红色游船上闭幕结束。大会的召开宣告了中国共产党的正式成立。",
