  "title": "红军长征",
  "short": "中央红军被迫战略转移，历时两年，行程二万五千里，最终胜利会师。",
  "detail": "长征是第一次国共内战后期，中国共产党领导的中国工农红军因在第五次反围剿战争中失利，进而实施的战略转移。1934年10月，红军主力自江西中央苏区及南方苏区出发，最终于1936年10月抵达陕西北部。",
