  "year": 1937,
  "date": "1937年",
  "title": "卢沟桥事变",
  "short": "日军借口士兵失踪进攻宛平城，中国守军奋起抵抗，全面抗战由此爆发。",
  "detail": "七七事变，又称卢沟桥抗战、卢沟桥事变、马可波罗桥事变，日方当时称北支事变。事变发生于1937年7月7日晚至8日凌晨，地点在北平西南的卢沟桥、宛平城（河北省宛平县）一带，交战双方为日本中国驻屯军与中国国民革命军第二十九军。该事件被认为是日本帝国主义发动全面侵华战争、中国全民族抗战的起点。",
