  "title": "中华人民共和国成立",
  "short": "10月1日，中华人民共和国中央人民政府成立。",
  "detail": "中华人民共和国中央人民政府成立典礼 （或称开国大典）是指1949年10月1日在北京（前称北平）为中华人民共和国中央人民政府成立而举行的仪式，标志着中华人民共和国的建立。中华人民共和国政府此后定10月1日为国庆节。",
