  "title": "唐山大地震",
  "short": "7.8级强烈地震摧毁唐山，造成24万余人遇难。",
  "detail": "唐山大地震是指于协调世界时1976年7月27日至28日发生在中华人民共和国河北省唐山市周边两次震级7以上的地震。主震于北京时间7月28日03时42分54秒，坐标39.570°N 117.978°E（唐山地区丰南县城西9千米、唐山市中心西南18千米），矩震级7.5级，震源深度23千米；第二次强震于北京时间7月28日18时45分35秒，矩震级7.4级，坐标39.664°N 118.401°E（唐山市东矿区的吕家坨矿以西2千米、唐山市中心以东19千米），震源深度26千米。。",
