  "major": false,
  "id": "e100",
  "year": 1980,
  "date": "1980年",
  "title": "设立深圳经济特区",
  "short": "深圳、珠海、汕头、厦门设立经济特区，成为对外开放的窗口和试验田。",
  "detail": "深圳经济特区，是位于中国广东省深圳市的经济特区，1980年8月26日设立。最初范围仅包括今日深圳市的罗湖、福田、南山、盐田等4区；至2010年5月31日，中华人民共和国国务院批准深圳市宝安、龙岗关外两区自该年7月1日起起划入深圳经济特区，使特区范围扩大至深圳全市。",
